import React, { useState } from 'react';
import axios from 'axios';
import './Register.css'; // Optional, for styling

const Register = () => {
  const [user, setUser] = useState({
    name: '',
    email: '',
    password: '',
    role: 'FARMER', // Default role
  });

  const [error, setError] = useState('');

  const handleChange = (e) => {
    const { name, value } = e.target;
    setUser({
      ...user,
      [name]: value,
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(''); // Reset error message before submitting

    // Prepare the payload to match backend expectations
    const payload = {
      name: user.name,
      email: user.email,
      password: user.password,
      roles: [{ name: user.role }], // Send roles as objects
    };

    try {
      const response = await axios.post('http://localhost:8080/api/users', payload);
      alert('Registration successful!');
      // Redirect or take necessary actions after successful registration
      // For example, redirect to login page:
      // history.push('/login');
    } catch (err) {
      if (err.response) {
        // Handle error response from the backend (e.g., email already in use)
        setError(err.response.data.message || 'Registration failed');
      } else {
        // Handle network errors or other errors
        setError('Error occurred while registering. Please try again.');
      }
    }
  };

  return (
    <div className="register-container">
      <h2>Register</h2>
      <form onSubmit={handleSubmit}>
        {error && <div className="error-message">{error}</div>}

        <div className="form-group">
          <label htmlFor="name">Name:</label>
          <input
            type="text"
            name="name"
            value={user.name}
            onChange={handleChange}
            required
          />
        </div>

        <div className="form-group">
          <label htmlFor="email">Email:</label>
          <input
            type="email"
            name="email"
            value={user.email}
            onChange={handleChange}
            required
          />
        </div>

        <div className="form-group">
          <label htmlFor="password">Password:</label>
          <input
            type="password"
            name="password"
            value={user.password}
            onChange={handleChange}
            required
          />
        </div>

        <div className="form-group">
          <label htmlFor="role">Role:</label>
          <select
            name="role"
            value={user.role}
            onChange={handleChange}
            required
          >
            <option value="FARMER">Farmer</option>
            <option value="BUYER">Buyer</option>
            <option value="ADMIN">Admin</option> {/* Add more roles if needed */}
          </select>
        </div>

        <button type="submit">Register</button>
      </form>
    </div>
  );
};

export default Register;
